  categories = { "ConflictError" },
  fields = { "resourceId", "resourceType" },
})
classes.InternalServerException = errors.define({
  tag = "InternalServerException",
  categories = { "ServerError", "RetryableError" },
  retryable = true,
  fields = { "retryAfterSeconds" },
})
classes.ResourceNotFoundException = errors.define({
  tag = "ResourceNotFoundException",
  categories = { "BadRequestError" },
  fields = { "resourceId", "resourceType" },
})
classes.ServiceQuotaExceededException = errors.define({
  tag = "ServiceQuotaExceededException",
  categories = { "QuotaError" },
  fields = { "resourceId", "resourceType", "serviceCode", "quotaCode" },
})
classes.ThrottlingException = errors.define({
  tag = "ThrottlingException",
  categories = { "ThrottlingError", "RetryableError" },
  retryable = true,
  throttling = true,
  fields = { "serviceCode", "quotaCode", "retryAfterSeconds" },
})
classes.ValidationException = errors.define({
  tag = "ValidationException",
  categories = { "BadRequestError" },
  fields = { "reason", "fieldList" },
})

